114	function buildRedteamFilterOptions(
115	  config?: Partial<UnifiedConfig> | null,
116	  table?: EvaluateTable | null,
117	): { plugin: string[]; strategy: string[]; severity: string[]; policy: string[] } | {} {
118	  const isRedteam = Boolean(config?.redteam);
119	
120	  // For non-redteam evaluations, don't provide redteam-specific filter options.
121	  // Note: This is separate from metadata filtering - if users have metadata fields
122	  // named "plugin", "strategy", or "severity", they can still filter on them using
123	  // the metadata filter type (which uses field/value pairs).
124	  if (!isRedteam) {
125	    return {};
126	  }
127	
128	  return {
129	    // Deduplicate plugins (handles custom plugins)
130	    plugin: Array.from(
131	      new Set(
132	        config?.redteam?.plugins?.map((plugin) =>
133	          typeof plugin === 'string' ? plugin : plugin.id,
134	        ) ?? [],
135	      ),
136	    ),
137	    strategy: extractUniqueStrategyIds(config?.redteam?.strategies),
138	    severity: computeAvailableSeverities(config?.redteam?.plugins),
139	    policy: buildPolicyOptions(config?.redteam?.plugins),
140	  };
