143	function computeAvailableSeverities(
144	  plugins?: Array<string | { id: string; severity?: string }> | null,
145	): string[] {
146	  if (!plugins || plugins.length === 0) {
147	    return [];
148	  }
149	
150	  // Get the risk category severity map with any overrides from plugins
151	  const severityMap = getRiskCategorySeverityMap(
152	    plugins.map((plugin) => (typeof plugin === 'string' ? { id: plugin } : plugin)) as any,
153	  );
154	
155	  // Extract unique severities from the map
156	  const severities = new Set<string>();
157	  Object.values(severityMap).forEach((severity) => {
158	    if (severity) {
159	      severities.add(severity);
160	    }
161	  });
162	
163	  // Return sorted array of severity values (in order of criticality)
164	  const severityOrder = [Severity.Critical, Severity.High, Severity.Medium, Severity.Low];
165	  return severityOrder.filter((sev) => severities.has(sev));
166	}
