56	/**
57	 * Sanitizes runtime options to ensure only JSON-serializable data is persisted.
58	 * Removes non-serializable fields like AbortSignal, functions, and symbols.
59	 */
60	function sanitizeRuntimeOptions(
61	  options?: Partial<import('../types').EvaluateOptions>,
62	): Partial<import('../types').EvaluateOptions> | undefined {
63	  if (!options) {
64	    return undefined;
65	  }
66	
67	  // Create a deep copy to avoid mutating the original
68	  const sanitized = { ...options };
69	
70	  // Remove known non-serializable fields
71	  delete (sanitized as any).abortSignal;
72	
73	  // Remove any function or symbol values
74	  for (const key in sanitized) {
75	    const value = (sanitized as any)[key];
76	    if (typeof value === 'function' || typeof value === 'symbol') {
77	      delete (sanitized as any)[key];
78	    }
79	  }
80	
81	  return sanitized;
82	}
